mapper.select:
SELECT o.order_id, o.order_number, o.order_type, o.total_price, o.order_status, o.created_at, ( SELECT p.payment_method FROM payments p WHERE p.order_id = o.order_id AND p.payment_status = '성공' ORDER BY p.payment_id DESC LIMIT 1 ) AS paymentMethod FROM orders o
DATE(o.created_at) = #{date}
AND o.order_type = #{orderType}
AND o.order_status = #{orderStatus}
ORDER BY o.order_id DESC

mapper.update:
UPDATE orders
SET order_status = #{orderStatus}
WHERE order_id = #{orderId}
AND order_status NOT IN ('완료', '취소')
